// 本轮调整：工具集简化、六项门禁只读、业务信号与工具映射收敛。
state.signalCatalog = (state.signalCatalog||[]).filter(x=>x.id!=='code' && x.id!=='sensitive');
function d82SignalTable(){
  const opts=[['none','仅记录'],['core','核心业务主线'],['money','账务 / 资金'],['multi','跨系统 / 异步'],['probe','精准测试工具'],['stableApi','接口自动化测试'],['stableUi','UI自动化测试']];
  const options=s=>opts.map(x=>`<option value="${x[0]}" ${x[0]===(s||'none')?'selected':''}>${x[1]}</option>`).join('');
  return `<div class="design-section signal-config"><div class="signal-config-head"><div><h3>业务与技术信号配置</h3><p>可新增、编辑、启用/停用；本次命中用于裁剪判断。工具映射用于推荐，不代替测试经理裁定。</p></div><button id="d82AddSignal" class="mini-btn">＋ 新增信号</button></div><table class="design-table signal-simple-table"><thead><tr><th>启用</th><th>信号</th><th>说明</th><th>本次命中</th><th>工具 / 规则映射</th><th></th></tr></thead><tbody>${state.signalCatalog.map((x,i)=>`<tr><td><input type="checkbox" data-d82-signal-enabled="${i}" ${x.enabled!==false?'checked':''}/></td><td><input data-d82-signal-title="${i}" value="${d82Esc(x.title||'')}"/></td><td><input data-d82-signal-desc="${i}" value="${d82Esc(x.desc||'')}"/></td><td><input type="checkbox" data-d82-signal-selected="${i}" ${x.selected?'checked':''} ${x.enabled===false?'disabled':''}/></td><td><select data-d82-signal-rule="${i}">${options(x.ruleKey)}</select></td><td><button class="mini-btn danger" data-d82-remove-signal="${i}">移除</button></td></tr>`).join('')}</tbody></table></div>`;
}

function d82RenderTools(){return `<div class="eyebrow">步骤 04 · 工具集选择</div><h2>按 9.3 裁剪明细选择适合工具</h2><p class="intro">本页只确认工具是否采用；具体输入、输出和操作规范由工具手册及项目执行记录承接。</p><table class="design-table tool-table tool-simple"><thead><tr><th>适合工具</th><th>适合场景</th><th>建议介入时机</th><th>是否采用</th></tr></thead><tbody>${d82Tools.map(x=>{const d=d82ToolChoice(x.id);return `<tr><td><b>${x.name}</b></td><td>${x.scene}</td><td>${x.when}</td><td><select data-d82-tool-decision="${x.id}">${['必用','条件使用','不使用'].map(v=>`<option ${v===d.decision?'selected':''}>${v}</option>`).join('')}</select></td></tr>`}).join('')}</tbody></table><div class="design-note"><b>选用原则：</b>测试经理根据已裁定的功能/非功能范围和工具前置条件确定采用范围；现有工具无法覆盖且人工执行风险、成本或周期不可接受时，再登记新增工具需求。</div>`;}

function d82RenderGates(){const extra=state.extraGates||[];return `<div class="eyebrow">步骤 05 · 门禁确认</div><h2>展示 6 项硬性门禁，再补充其他条款</h2><p class="intro">以下 6 项来自 0826 版准出门禁，默认纳入硬性门禁，只展示不勾选；不满足时流程阻断。项目可在下方补充其他条款。</p><table class="design-table gate-table"><thead><tr><th>硬性指标</th><th>计算方式</th><th>判定标准</th><th>门禁属性</th></tr></thead><tbody>${d82HardGates.map(x=>`<tr><td><b>${x.name}</b></td><td class="gate-formula">${x.formula}</td><td>${x.threshold}</td><td class="gate-readonly">默认必须</td></tr>`).join('')}</tbody></table><div class="design-section"><div class="signal-config-head"><div><h3>额外门禁条款</h3><p>额外条款可设置为硬性、软性或红线；只有额外硬性条款需要确认。</p></div><button id="d82AddGate" class="mini-btn">＋ 新增条款</button></div><table class="design-table"><thead><tr><th>条款</th><th>计算 / 判定方式</th><th>类型</th><th>确认</th><th></th></tr></thead><tbody>${extra.map((x,i)=>`<tr><td><input data-d82-extra-name="${i}" value="${d82Esc(x.name)}"/></td><td><input data-d82-extra-rule="${i}" value="${d82Esc(x.rule)}"/></td><td><select data-d82-extra-kind="${i}">${['硬性','软性','红线'].map(v=>`<option ${v===x.kind?'selected':''}>${v}</option>`).join('')}</select></td><td><input type="checkbox" data-d82-extra-check="${i}" ${x.checked?'checked':''}/></td><td><button class="mini-btn danger" data-d82-remove-extra="${i}">移除</button></td></tr>`).join('')}</tbody></table></div><div class="design-note"><b>默认门禁：</b>6 项指标直接纳入最终指引，不需要逐项勾选；额外硬性条款若未确认，仍会阻断最终输出。</div>`}

d82AllHardChecked = function(){return (state.extraGates||[]).filter(x=>x.kind==='硬性').every(x=>x.checked);};
const d82MakeOutputGateFixBase = d82MakeOutput;
d82MakeOutput = function(){let html=d82MakeOutputGateFixBase();d82HardGates.forEach(x=>{html=html.replace(`${x.name}</b>：${x.threshold}；未确认`,`${x.name}</b>：${x.threshold}；默认硬性门禁`)});return html;};
d82RenderStep();
